import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"菜单与路由","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/routing.md","filePath":"frontend/routing.md","lastUpdated":1794049926000}`),a={name:`frontend/routing.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="菜单与路由" tabindex="-1">菜单与路由 <a class="header-anchor" href="#菜单与路由" aria-label="Permalink to “菜单与路由”">​</a></h1><p>本页说明前端的路由组成、菜单来源、组件解析与路由守卫，适用于前端开发者。</p><p>后端菜单驱动动态路由：<code>packages/router</code> 提供守卫（<code>guard.ts</code>）、菜单 → 路由（<code>dynamic.ts</code>）、核心路由（<code>routes/core.ts</code>）与视图解析（<code>views.ts</code>），菜单与权限的数据来自 <code>auth.permissions</code>，组件按页面登记的组件路径精确解析。</p><h2 id="三类路由" tabindex="-1">三类路由 <a class="header-anchor" href="#三类路由" aria-label="Permalink to “三类路由”">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>定义位置</th><th>例子</th></tr></thead><tbody><tr><td>核心路由</td><td><code>packages/router/routes/core.ts</code></td><td><code>/auth/login</code>、<code>/auth/code-login</code>、<code>/auth/email-login</code>、<code>/auth/forget-password</code>、<code>/auth/register</code>、<code>/auth/oauth-callback</code>、<code>/403</code>、<code>/404</code>、<code>/500</code>、兜底</td></tr><tr><td>应用静态路由</td><td><code>src/router/routes.ts</code></td><td><code>RootLayout</code>（<code>/</code>，承载业务页）、<code>/profile</code>（个人中心，挂在主布局下、不进菜单）、<code>/control-center</code>、<code>/oauth/authorize</code></td></tr><tr><td>动态路由</td><td>菜单树（<code>auth.permissions</code>）</td><td><code>/identity/users</code>、<code>/settings/configs</code> …</td></tr></tbody></table><p>地址缺省走 hash；<code>VITE_ROUTER_HISTORY=history</code> 切 HTML5 历史（静态托管要回退到 <code>index.html</code>），<code>VITE_BASE</code> 设部署子路径。</p><h2 id="菜单来源" tabindex="-1">菜单来源 <a class="header-anchor" href="#菜单来源" aria-label="Permalink to “菜单来源”">​</a></h2><ol><li>后端各包在 <code>&lt;包&gt;Pages.cs</code> 登记页面：页面码、路由、文案键、图标、排序、所需权限码与所在目录；</li><li>种子把页面对齐成菜单，运营可在菜单管理里改展示、启停、配徽标、加目录（可多级嵌套）与外链；</li><li><code>auth.permissions</code> 返回按权限裁剪的菜单树（停用的节点连同子树不下发，也就没有路由），以及有效权限码、角色与页面码。</li></ol><p>前端把菜单树投影成路由（<code>toMenuRoutes</code>）：</p><table tabindex="0"><thead><tr><th>菜单字段</th><th>路由</th></tr></thead><tbody><tr><td><code>route</code>、<code>code</code></td><td><code>path</code>、<code>name</code>（目录与外链没有路由，用 <code>/&lt;code&gt;</code> 占位，不生成路由记录）</td></tr><tr><td><code>component</code></td><td>页面节点的视图</td></tr><tr><td><code>title</code> / <code>titleKey</code></td><td><code>meta.title</code>：运营改过或新建的节点给原文，其余给文案键</td></tr><tr><td><code>hidden</code>、<code>keepAlive</code>、<code>affix</code></td><td><code>meta.hidden</code>、<code>meta.keepAlive</code>、<code>meta.affixTab</code></td></tr><tr><td><code>permission</code></td><td><code>meta.permissions</code></td></tr><tr><td><code>badge</code>、<code>badgeType</code>、<code>badgeDot</code></td><td><code>meta.badge</code>、<code>meta.badgeType</code>、<code>meta.dot</code>，由 <code>MenuBadge</code> 渲染</td></tr><tr><td>外链的 <code>externalUrl</code></td><td><code>meta.link</code>，点击时新标签打开</td></tr></tbody></table><p>目录节点自动重定向到第一个可导航的子页。侧栏会展开到当前页：按地址直达、刷新或从标签页切过来时，通往当前页的各级目录自动展开；手动收起的目录在当前页换掉之前不会被重新打开。</p><h2 id="组件解析" tabindex="-1">组件解析 <a class="header-anchor" href="#组件解析" aria-label="Permalink to “组件解析”">​</a></h2><p>页面节点的 <code>component</code> 是 <code>&lt;包&gt;/&lt;路径&gt;/index</code>，前端在 <code>src/modules/*/views/**/index.vue</code> 里精确匹配，不做多候选猜测：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>component: settings/configs/index  →  src/modules/settings/views/configs/index.vue</span></span></code></pre></div><ul><li>壳层自带、不归任何模块的页面在 <code>packages/router/views.ts</code> 的 <code>coreViews</code> 里逐条登记（关于页 <code>about/project/index</code> → <code>packages/views/_core/about/index.vue</code>）；</li><li>登记了组件路径但找不到文件：控制台报错并回落到 404 页（侧栏仍显示该条目，报错用于定位配置错误）；菜单缺路由名的节点同样报错并跳过；</li><li>视图路径要求 kebab-case 且全局唯一，由 <code>pnpm modules:check</code> 检查；</li><li>每个页面包一层「名字 = 路由名」的壳组件，KeepAlive 按路由名命中缓存，页面组件自己的名字不参与；</li><li>审批中心按审批业务登记的单据组件路径（如 <code>access/permission-request-approval/index</code>）用同一个 <code>resolveView</code> 加载。</li></ul><h2 id="守卫" tabindex="-1">守卫 <a class="header-anchor" href="#守卫" aria-label="Permalink to “守卫”">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>处理</th></tr></thead><tbody><tr><td>未登录</td><td>认证页与 <code>/403</code>、<code>/404</code>、<code>/500</code> 放行；其余带回跳地址送到登录页</td></tr><tr><td>已登录访问第三方回调页</td><td>放行（个人中心发起的账号绑定要在这里确认）</td></tr><tr><td>已登录访问其他认证页</td><td>回首页</td></tr><tr><td>首次进入（含刷新页面、打开深链）</td><td>调 <code>auth.permissions</code> 装载动态路由，再从后端拉取偏好；按 path + query + hash 重进（深链的查询串与 OAuth 的 <code>?code=</code> 不丢）</td></tr><tr><td>装载失败</td><td>进 <code>/500</code>；权限没写进 store，下一次导航会重试</td></tr><tr><td>会话锁定</td><td>直接放行挂壳，由锁屏遮罩盖住，解锁后重新走守卫</td></tr><tr><td>会话已失效</td><td>回登录页，带上原路径</td></tr><tr><td>匹配不到路由</td><td>进 <code>/404</code></td></tr><tr><td><code>meta.permissions</code> 不在有效权限里</td><td>进 <code>/403</code></td></tr><tr><td>独立公共页（<code>meta.standalone</code>，如控制中心、OAuth 同意页）</td><td>不挂主布局、不进标签栏；错误页同样不进标签栏</td></tr></tbody></table><p>刷新令牌后权限清空、下一次导航重取，角色指派的变化随之生效；切换租户、切换激活角色、开始或结束模仿后整页重建（<code>relaunchApp</code>）。</p><p>未读的强制阅读公告不在守卫里处理：主布局挂载时拉取，以不可关闭的弹窗逐条拦截，读完才能继续操作。</p><h2 id="首页" tabindex="-1">首页 <a class="header-anchor" href="#首页" aria-label="Permalink to “首页”">​</a></h2><p>登录后的落点与 <code>/</code> 的跳转目标取菜单树里第一个显示的页面（深度优先），它也是固定的首页标签。菜单里没有页面时用 <code>VITE_HOME_PATH</code> 兜底（仓库的 <code>.env</code> 设为 <code>/workbench/dashboard</code>）；关掉后端工作台模块时把它留空。</p><h2 id="标签页与缓存" tabindex="-1">标签页与缓存 <a class="header-anchor" href="#标签页与缓存" aria-label="Permalink to “标签页与缓存”">​</a></h2><p>访问过的页面进标签栏（首页与固定标签不可关）。标签标题存文案键，切换语言时跟着变。偏好里可关掉访问历史（只留当前页）或限制标签数。菜单的「缓存」与「固定标签」两个展示字段在菜单管理里可调，后端登记给缺省值。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./permission">权限与脱敏</a> · <a href="./development">开发流程</a> · <a href="./../backend/permission">后端权限管理</a></li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};